<script setup>import { ref } from 'vue'; import { router } from '@inertiajs/vue3'; const props=defineProps({ url:String, title:{type:String,default:'¿Eliminar este registro?'}, message:{type:String,default:'Esta acción no se puede deshacer.'} }); const open=ref(false); const remove=()=>router.delete(props.url,{onFinish:()=>open.value=false});</script>
<template><button class="btn-danger" type="button" @click="open=true"><slot>Eliminar</slot></button><Teleport to="body"><div v-if="open" class="fixed inset-0 z-[80] grid place-items-center bg-slate-950/50 p-4"><div class="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><h3 class="text-lg font-bold text-slate-950">{{ title }}</h3><p class="mt-2 text-sm text-slate-500">{{ message }}</p><div class="mt-6 flex justify-end gap-2"><button class="btn-secondary" @click="open=false">Cancelar</button><button class="btn-danger" @click="remove">Sí, eliminar</button></div></div></div></Teleport></template>
